// WordprocessingML fixtures for the Office-free tests.
//
// Not a test file itself (the runner globs `*.test.mjs`), and deliberately not
// generated by Word: the point of these tests is that they run on
// `ubuntu-latest`, where Office does not exist.
//
// The default style table is **German**, and matches what Word on this machine
// actually writes -- measured by unzipping a Word-authored .docx and reading
// `word/styles.xml` out of it directly.
//
// The surprise worth recording: the style id for heading 1 is `berschrift1`,
// not `Überschrift1`. Word derives the id from the localized style name
// ("Überschrift 1") and drops the non-ASCII characters on the way, so the
// umlaut is simply gone. Code that hardcoded the English name *or* the obvious
// German spelling would find nothing.
//
// What is stable is `w:name`, which holds the canonical built-in name
// ("heading 1") whatever the UI language is. That is why resolution goes
// through the styles part, and why a style id is only ever carried, never
// matched.

const esc = (value) =>
    String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");

/** A style definition, in the shape Word writes it. */
export function style({ styleId, name, basedOn = null, outlineLevel = null, type = "paragraph" }) {
    return [
        `<w:style w:type="${type}" w:styleId="${esc(styleId)}">`,
        `<w:name w:val="${esc(name)}"/>`,
        basedOn ? `<w:basedOn w:val="${esc(basedOn)}"/>` : "",
        outlineLevel === null ? "" : `<w:pPr><w:outlineLvl w:val="${outlineLevel}"/></w:pPr>`,
        `</w:style>`,
    ].join("");
}

export const GERMAN_STYLES = [
    style({ styleId: "Standard", name: "Normal" }),
    // The id Word actually writes on a German install: umlaut stripped.
    style({ styleId: "berschrift1", name: "heading 1" }),
    style({ styleId: "berschrift2", name: "heading 2" }),
    // A custom style: name localized too, so only w:outlineLvl resolves it. The
    // id keeps its umlaut, which is legal -- the stripping is Word's own habit
    // when minting an id, not a rule the format imposes. Resolution must be
    // indifferent to both.
    style({ styleId: "Kapitelüberschrift", name: "Kapitelüberschrift", outlineLevel: 1 }),
    // Inherits its outline level rather than restating it.
    style({ styleId: "Unterkapitel", name: "Unterkapitel", basedOn: "Kapitelüberschrift" }),
];

/**
 * A paragraph. `runs` may be plain strings (a `w:t` each) or raw markup, which
 * is how a test injects a tab, a break, or a tracked deletion.
 */
export function paragraph(text, { styleId = null, outlineLevel = null, numbering = null, raw = null } = {}) {
    const properties = [
        styleId ? `<w:pStyle w:val="${esc(styleId)}"/>` : "",
        outlineLevel === null ? "" : `<w:outlineLvl w:val="${outlineLevel}"/>`,
        numbering ? `<w:numPr><w:ilvl w:val="${numbering.level}"/><w:numId w:val="${numbering.numId}"/></w:numPr>` : "",
    ].join("");
    const content = raw ?? (text === "" ? "" : `<w:r><w:t xml:space="preserve">${esc(text)}</w:t></w:r>`);
    return `<w:p>${properties ? `<w:pPr>${properties}</w:pPr>` : ""}${content}</w:p>`;
}

/** A one-column table, one paragraph per row. */
export function table(rows) {
    const cells = rows.map((row) => `<w:tr><w:tc>${paragraph(row)}</w:tc></w:tr>`).join("");
    return `<w:tbl>${cells}</w:tbl>`;
}

/** A bare `w:document`, with no package around it and therefore no styles part. */
export function bareDocument(body) {
    return [
        `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>`,
        `<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">`,
        `<w:body>${Array.isArray(body) ? body.join("") : body}</w:body>`,
        `</w:document>`,
    ].join("");
}

/** The Flat OPC package `Range.WordOpenXML` returns: document part plus styles part. */
export function flatOpc(body, styles = GERMAN_STYLES) {
    const documentPart = [
        `<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"`,
        ` xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006">`,
        `<w:body>${Array.isArray(body) ? body.join("") : body}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/></w:sectPr></w:body>`,
        `</w:document>`,
    ].join("");
    const stylesPart = [
        `<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">`,
        `<w:latentStyles w:count="376"><w:lsdException w:name="Normal"/></w:latentStyles>`,
        styles.join(""),
        `</w:styles>`,
    ].join("");

    return [
        `<?xml version="1.0" standalone="yes"?>`,
        `<?mso-application progid="Word.Document"?>`,
        `<pkg:package xmlns:pkg="http://schemas.microsoft.com/office/2006/xmlPackage">`,
        `<pkg:part pkg:name="/word/document.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml">`,
        `<pkg:xmlData>${documentPart}</pkg:xmlData></pkg:part>`,
        `<pkg:part pkg:name="/word/styles.xml" pkg:contentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml">`,
        `<pkg:xmlData>${stylesPart}</pkg:xmlData></pkg:part>`,
        `</pkg:package>`,
    ].join("");
}
